const NUMBERS_OF = { moves: ['d', 'c'], outfits: ['price', 'min'], hairs: ['price', 'min'], shoes: ['price'], accs: ['price'], pieces: ['price'], snacks: ['price'], upgrades: ['price'], numbers: [] };
