// Runs the app's script files the way NodeGX does (each once, use() between them) on the starting save and on a
// played-through one, so a typo in a view or an action shows here rather than as a blank tab.
import { readFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const cache = {};
export function use(path) {

==> tools/extract-words.mjs <==
// One-off: turns reference/src/i18n.js (words + sentence functions) into rows { key, fr, en } for the NodeGX
// "Words" Static Data node. A sentence function becomes a template: {0} {1}… are its arguments, {0:s} is "s" when
// argument 0 is more than 1, {0:lower} lower-cases it. Functions with logic beyond that are written out by hand below.
// Usage: node tools/extract-words.mjs > tools/words.json
import { dirname, join } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');

==> tools/check.src.js <==
// What a grown-up may change, and how far. The same code runs in the cloud function that saves a change (so a child
// cannot get round it from the page) and in the browser before a change is laid over the game (so a bad row that got
// into the database some other way never reaches the screen). It has no imports: the ids it knows are written in by
// tools/sync-check.mjs from gala-rules/src/data.js.
const KNOWN = __KNOWN__;

// every table a grown-up may touch, the fields of an existing row they may change, and the fields a new row must have
const TABLES = {
key,fr,en
school,École de danse Étoile,Star Dance School
lang,EN,FR
// The frame around the 3D view: the top bar, the tabs, the camera bar and the buttons at the foot of the sheet.
// From reference/src/ui.js hud(), paintCamBar(), paintSheet() and paintRunSheet()'s button row.
const { rules } = use('view/common');

const TAB_KEYS = (save) => ['order', 'formation', 'gouter', 'costumes', 'build', ...(rules(save).parking ? ['parking'] : []), 'shop', 'notebook'];
const currentTab = (save, ui) => (TAB_KEYS(save).includes(ui.tab) ? ui.tab : 'order');

function top(save, ui, w) {
  const live = ui.live;
  return {
    brand: (save.school.name || '').trim() || w('school'),
    season: w('season', save.season),
    stars: w('stars', save.school.stars),
    day: live && !live.done ? `${w(`live_${live.mode}`)} · ${w.clock(live.t, false)}` : '',
    sound: save.sound !== false ? '🔊' : '🔇',
    soundTitle: w(save.sound !== false ? 'sound_on' : 'sound_off'),
    lang: w('lang'),
  };
}

const tabs = (save, ui, w) => TAB_KEYS(save).map((k) => ({ id: k, label: w(`tabs_${k}`), pressed: k === currentTab(save, ui) }));

// the buttons at the foot of the sheet, by screen
function go(save, ui, w) {
  const live = ui.live || {}, mode = live.mode;
  const b = (id, label, kind, wide) => ({ id, label, kind, wide: !!wide });
  if (ui.screen === 'run') {
    return [
      b('speed', `⏩ ${w('speed')} ×${ui.speed || 1}`, 'reh'),
      ...(mode !== 'try' ? [b('follow', `${w('follow')} ${ui.follow !== false ? '✓' : ''}`, 'reh')] : []),
